// Generated by pluto contracts generate from the bridge schema. Do not edit.
// It runs every golden vector through the codec API (Bridge.parseNativeToWeb, Bridge.parseWebToNative, Bridge.encode).
// Put bridge.vectors.json on the test classpath (src/test/resources).
package dev.pluto.bridge

import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.jupiter.api.DynamicTest
import org.junit.jupiter.api.TestFactory

class BridgeConformanceTest {
    private class Vector(val name: String, val json: String, val nativeToWeb: String, val webToNative: String)

    private val vectors: List<Vector> =
        Json.parseToJsonElement(BridgeConformanceTest::class.java.getResourceAsStream("/bridge.vectors.json")!!.readBytes().decodeToString()).jsonArray.map {
            val o = it.jsonObject
            Vector(o["name"]!!.jsonPrimitive.content, o["json"]!!.jsonPrimitive.content, o["nativeToWeb"]!!.jsonPrimitive.content, o["webToNative"]!!.jsonPrimitive.content)
        }

    private fun outcome(parse: (String) -> Any, json: String): String = try {
        parse(json)
        "accept"
    } catch (e: Exception) {
        "refuse"
    }

    @TestFactory
    fun vectors(): List<DynamicTest> = vectors.map { v ->
        DynamicTest.dynamicTest(v.name) {
            assertEquals(v.nativeToWeb, outcome({ Bridge.parseNativeToWeb(it) }, v.json), "${v.name}: native-to-web")
            assertEquals(v.webToNative, outcome({ Bridge.parseWebToNative(it) }, v.json), "${v.name}: web-to-native")
        }
    }

    @TestFactory
    fun credentialsStayOutOfToString(): List<DynamicTest> = vectors.filter { it.nativeToWeb == "accept" || it.webToNative == "accept" }.map { v ->
        DynamicTest.dynamicTest("no credential in toString ${v.name}") {
            val message: Any = if (v.nativeToWeb == "accept") Bridge.parseNativeToWeb(v.json) else Bridge.parseWebToNative(v.json)
            val payload = Json.parseToJsonElement(v.json).jsonObject["payload"]!!.jsonObject
            for ((key, value) in payload) {
                val secret = Regex("token|secret|password|credential", RegexOption.IGNORE_CASE).containsMatchIn(key)
                if (secret && value.jsonPrimitive.isString) assertFalse(message.toString().contains(value.jsonPrimitive.content), "${v.name}: $key is printed by toString")
            }
        }
    }

    @TestFactory
    fun roundtrips(): List<DynamicTest> = vectors.filter { it.nativeToWeb == "accept" || it.webToNative == "accept" }.map { v ->
        DynamicTest.dynamicTest("roundtrip ${v.name}") {
            if (v.nativeToWeb == "accept") {
                val message = Bridge.parseNativeToWeb(v.json)
                assertEquals(message, Bridge.parseNativeToWeb(Bridge.encode(message)))
            } else {
                val message = Bridge.parseWebToNative(v.json)
                assertEquals(message, Bridge.parseWebToNative(Bridge.encode(message)))
            }
        }
    }
}
